const area: Record<string, Record<string, string>> = {"asp-net-typescript-mapping":{"overview":"<div class=\"table-scroll\"><table><thead><tr><th>ASP.NET AJAX Control Toolkit</th><th>TypeScript (<code>@wf-controls/core</code>)</th><th>React adapter</th><th>Notes</th></tr></thead><tbody><tr><td><code>ModalPopupExtender</code></td><td><code>ModalBehavior</code> / <code>ModalBehaviorOptions</code></td><td><code>&lt;WebFormsModal /&gt;</code></td><td><code>OkControlID</code>/<code>CancelControlID</code> -&gt; <code>handleOk()</code>/<code>handleCancel()</code>.</td></tr><tr><td><code>TabContainer</code> / <code>TabPanel</code></td><td><code>TabsController</code> / <code>TabItem</code></td><td><code>&lt;WebFormsTabs /&gt;</code></td><td><code>ActiveTabIndex</code>, <code>OnActiveTabChanged</code>.</td></tr><tr><td><code>Accordion</code> / <code>AccordionPane</code></td><td><code>AccordionController</code> / <code>AccordionPaneItem</code></td><td>(none in React package)</td><td><code>SelectedIndex</code>; <code>-1</code> = all collapsed.</td></tr><tr><td><code>AutoCompleteExtender</code></td><td><code>AutoCompleteBehavior</code> / <code>AutoCompleteOptions</code></td><td></td><td><code>ServiceMethod</code> is stored; real fetching is <code>onSearch</code>.</td></tr><tr><td><code>ConfirmButtonExtender</code></td><td><code>ConfirmButtonBehavior</code> / <code>ConfirmButtonOptions</code></td><td></td><td>Uses <code>window.confirm</code>.</td></tr><tr><td><code>CollapsiblePanelExtender</code></td><td><code>CollapsiblePanelBehavior</code> / <code>CollapsiblePanelOptions</code></td><td></td><td></td></tr><tr><td><code>CascadingDropDown</code></td><td><code>CascadingDropDownBehavior</code> / <code>CascadingDropDownOptions</code></td><td></td><td><code>LoadItems</code> replaces <code>ServicePath</code>/<code>ServiceMethod</code>.</td></tr><tr><td><code>EventHandler</code></td><td><code>EventDispatcher&lt;TSender, TArgs&gt;</code></td><td></td><td><code>subscribe(handler)</code> returns an unsubscribe function; handlers are awaited in order.</td></tr></tbody></table></div>\n<hr>\n"},"quick-start":{"overview":"<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">import</span> { <span class=\"tok-t\">ModalBehavior</span>, <span class=\"tok-t\">TabsController</span>, <span class=\"tok-t\">AccordionController</span>, <span class=\"tok-t\">AutoCompleteBehavior</span>,\n         <span class=\"tok-t\">ConfirmButtonBehavior</span>, <span class=\"tok-t\">CollapsiblePanelBehavior</span>, <span class=\"tok-t\">CascadingDropDownBehavior</span> } <span class=\"tok-k\">from</span> <span class=\"tok-s\">&quot;@wf-controls/core&quot;</span>;\n\n<span class=\"tok-k\">const</span> modal = <span class=\"tok-k\">new</span> <span class=\"tok-t\">ModalBehavior</span>({ onOk: <span class=\"tok-k\">async</span> () =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;saved&quot;</span>) });\nmodal.shown.<span class=\"tok-f\">subscribe</span>(() =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;shown&quot;</span>));\n<span class=\"tok-k\">await</span> modal.<span class=\"tok-f\">show</span>();         <span class=\"tok-c\">// -&gt; shown</span>\n<span class=\"tok-k\">await</span> modal.<span class=\"tok-f\">handleOk</span>();     <span class=\"tok-c\">// -&gt; saved  (then ok event, then hidden)</span>\n\n<span class=\"tok-k\">const</span> tabs = <span class=\"tok-k\">new</span> <span class=\"tok-t\">TabsController</span>({ tabs: [{ id: <span class=\"tok-s\">&quot;a&quot;</span>, headerText: <span class=\"tok-s\">&quot;A&quot;</span> }, { id: <span class=\"tok-s\">&quot;b&quot;</span>, headerText: <span class=\"tok-s\">&quot;B&quot;</span> }] });\ntabs.activeTabChanged.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;tab&quot;</span>, e.activeIndex));\n<span class=\"tok-k\">await</span> tabs.<span class=\"tok-f\">setActiveTab</span>(<span class=\"tok-n\">1</span>); <span class=\"tok-c\">// -&gt; tab 1</span></code></pre></div>\n<hr>\n"},"event-model-used-by-behaviors":{"overview":"<p><code>EventDispatcher&lt;TSender, TArgs&gt;</code>:</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>subscribe</code></td><td><code>(handler: (sender, args) =&gt; void | Promise&lt;void&gt;) =&gt; () =&gt; void</code></td><td>Adds a handler; returns an unsubscribe function.</td></tr><tr><td><code>emit</code></td><td><code>(sender, args) =&gt; Promise&lt;void&gt;</code></td><td>Awaits handlers sequentially in subscription order (iterating a snapshot). A throwing handler rejects the <code>emit</code> promise.</td></tr><tr><td><code>clear</code></td><td><code>() =&gt; void</code></td><td>Removes all handlers.</td></tr></tbody></table></div>\n<p>Behavior events use <code>this</code> as the sender type. Their args are small plain objects (listed per class). None extend <code>CancelEventArgs</code>.</p>\n<hr>\n"},"modalbehavior":{"overview":"<p>Open/closed state with OK/Cancel handling. ASP.NET equivalent: <code>ModalPopupExtender</code>.</p>\n","constructor-options-modalbehavioroptions":"<h3 id=\"31-constructor-options-modalbehavioroptions\">3.1 Constructor options (<code>ModalBehaviorOptions</code>)<a class=\"anchor\" href=\"#31-constructor-options-modalbehavioroptions\" aria-label=\"Link to this section\">#</a></h3>\n<p>Constructor: <code>new ModalBehavior(options: ModalBehaviorOptions = {})</code>. <code>options</code> is a public mutable field.</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint (unused by core).</td></tr><tr><td><code>targetControlId</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint: trigger element.</td></tr><tr><td><code>popupControlId</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint: popup element.</td></tr><tr><td><code>okControlId</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>cancelControlId</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>backgroundCssClass</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>dropShadow</code></td><td><code>boolean</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>onOk</code></td><td><code>() =&gt; Promise&lt;void&gt; | void</code></td><td><code>undefined</code></td><td>Awaited by <code>handleOk()</code> before the <code>ok</code> event.</td></tr><tr><td><code>onCancel</code></td><td><code>() =&gt; void</code></td><td><code>undefined</code></td><td>Called (not awaited) by <code>handleCancel()</code> before the <code>cancel</code> event.</td></tr></tbody></table></div>\n","properties":"<h3 id=\"32-properties\">3.2 Properties<a class=\"anchor\" href=\"#32-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>ModalBehaviorOptions</code></td><td>rw</td><td><code>{}</code></td><td></td></tr><tr><td><code>isOpen</code></td><td><code>boolean</code></td><td>r</td><td><code>false</code></td><td></td></tr></tbody></table></div>\n","methods":"<h3 id=\"33-methods\">3.3 Methods<a class=\"anchor\" href=\"#33-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>show()</code></td><td><code>Promise&lt;void&gt;</code></td><td>handler rejection</td><td>If closed: <code>isOpen = true</code>, raises <code>shown</code>. No-op if already open.</td></tr><tr><td><code>hide()</code></td><td><code>Promise&lt;void&gt;</code></td><td>handler rejection</td><td>If open: <code>isOpen = false</code>, raises <code>hidden</code>. No-op if already closed.</td></tr><tr><td><code>handleOk()</code></td><td><code>Promise&lt;void&gt;</code></td><td><code>onOk</code> / handler rejection</td><td>Awaits <code>options.onOk</code>, raises <code>ok</code>, then <code>hide()</code>. Runs even if the modal is closed (<code>hidden</code> is then not raised). If <code>onOk</code> throws, the modal stays open and neither <code>ok</code> nor <code>hide</code> run.</td></tr><tr><td><code>handleCancel()</code></td><td><code>Promise&lt;void&gt;</code></td><td><code>onCancel</code> / handler rejection</td><td>Calls <code>options.onCancel</code>, raises <code>cancel</code>, then <code>hide()</code>.</td></tr></tbody></table></div>\n","events":"<h3 id=\"34-events\">3.4 Events<a class=\"anchor\" href=\"#34-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>shown</code></td><td><code>void</code></td><td>no</td><td>After <code>isOpen</code> became <code>true</code>.</td><td>none</td></tr><tr><td><code>hidden</code></td><td><code>void</code></td><td>no</td><td>After <code>isOpen</code> became <code>false</code>.</td><td>none</td></tr><tr><td><code>ok</code></td><td><code>void</code></td><td>no</td><td>In <code>handleOk()</code>, after <code>onOk</code>, before hiding.</td><td>none</td></tr><tr><td><code>cancel</code></td><td><code>void</code></td><td>no</td><td>In <code>handleCancel()</code>, after <code>onCancel</code>, before hiding.</td><td>none</td></tr></tbody></table></div>\n<p>Order: <code>handleOk</code> -&gt; <code>onOk</code> -&gt; <code>ok</code> -&gt; <code>hidden</code>. <code>handleCancel</code> -&gt; <code>onCancel</code> -&gt; <code>cancel</code> -&gt; <code>hidden</code>.</p>\n<blockquote class=\"\"><p><code>ok</code>/<code>cancel</code> cannot veto the close. To keep the dialog open on validation failure, validate before calling <code>handleOk()</code>, or throw from <code>onOk</code> (the modal then stays open).</p></blockquote>\n","example":"<h3 id=\"35-example\">3.5 Example<a class=\"anchor\" href=\"#35-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> order = [];\n<span class=\"tok-k\">const</span> m = <span class=\"tok-k\">new</span> <span class=\"tok-t\">ModalBehavior</span>({ id: <span class=\"tok-s\">&quot;m1&quot;</span>, onOk: <span class=\"tok-k\">async</span> () =&gt; { order.<span class=\"tok-f\">push</span>(<span class=\"tok-s\">&quot;onOk&quot;</span>); }, onCancel: () =&gt; order.<span class=\"tok-f\">push</span>(<span class=\"tok-s\">&quot;onCancel&quot;</span>) });\nm.shown.<span class=\"tok-f\">subscribe</span>(() =&gt; order.<span class=\"tok-f\">push</span>(<span class=\"tok-s\">&quot;shown&quot;</span>)); m.hidden.<span class=\"tok-f\">subscribe</span>(() =&gt; order.<span class=\"tok-f\">push</span>(<span class=\"tok-s\">&quot;hidden&quot;</span>));\nm.ok.<span class=\"tok-f\">subscribe</span>(() =&gt; order.<span class=\"tok-f\">push</span>(<span class=\"tok-s\">&quot;ok&quot;</span>));       m.cancel.<span class=\"tok-f\">subscribe</span>(() =&gt; order.<span class=\"tok-f\">push</span>(<span class=\"tok-s\">&quot;cancel&quot;</span>));\nconsole.<span class=\"tok-f\">log</span>(m.isOpen);                          <span class=\"tok-c\">// -&gt; false</span>\n<span class=\"tok-k\">await</span> m.<span class=\"tok-f\">show</span>(); <span class=\"tok-k\">await</span> m.<span class=\"tok-f\">show</span>();                 <span class=\"tok-c\">// second call is a no-op</span>\nconsole.<span class=\"tok-f\">log</span>(m.isOpen);                          <span class=\"tok-c\">// -&gt; true</span>\n<span class=\"tok-k\">await</span> m.<span class=\"tok-f\">handleOk</span>();\nconsole.<span class=\"tok-f\">log</span>(m.isOpen, order.<span class=\"tok-f\">join</span>(<span class=\"tok-s\">&quot; &quot;</span>));         <span class=\"tok-c\">// -&gt; false shown onOk ok hidden</span>\norder.length = <span class=\"tok-n\">0</span>; <span class=\"tok-k\">await</span> m.<span class=\"tok-f\">show</span>(); <span class=\"tok-k\">await</span> m.<span class=\"tok-f\">handleCancel</span>();\nconsole.<span class=\"tok-f\">log</span>(order.<span class=\"tok-f\">join</span>(<span class=\"tok-s\">&quot; &quot;</span>));                   <span class=\"tok-c\">// -&gt; shown onCancel cancel hidden</span>\norder.length = <span class=\"tok-n\">0</span>; <span class=\"tok-k\">await</span> m.<span class=\"tok-f\">handleOk</span>();           <span class=\"tok-c\">// while closed</span>\nconsole.<span class=\"tok-f\">log</span>(order.<span class=\"tok-f\">join</span>(<span class=\"tok-s\">&quot; &quot;</span>));                   <span class=\"tok-c\">// -&gt; onOk ok</span></code></pre></div>\n<hr>\n"},"tabscontroller":{"overview":"<p>Tab selection state. ASP.NET equivalent: <code>TabContainer</code>.</p>\n","types-and-constructor-options":"<h3 id=\"41-types-and-constructor-options\">4.1 Types and constructor options<a class=\"anchor\" href=\"#41-types-and-constructor-options\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">interface</span> <span class=\"tok-t\">TabItem</span> { id: string; headerText: string; enabled?: boolean; visible?: boolean }\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">TabsControllerOptions</span> {\n  activeTabIndex?: number;\n  tabs?: <span class=\"tok-t\">TabItem</span>[];\n  onActiveTabChanged?: (newIndex: number) =&gt; <span class=\"tok-k\">void</span>;\n}</code></pre></div>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>activeTabIndex</code></td><td><code>number</code></td><td><code>0</code></td><td>Initial index. <strong>Not validated</strong> against <code>tabs</code> (5 with one tab stays 5).</td></tr><tr><td><code>tabs</code></td><td><code>TabItem[]</code></td><td><code>[]</code></td><td>Stored by reference (not copied) in the constructor.</td></tr><tr><td><code>onActiveTabChanged</code></td><td><code>(newIndex: number) =&gt; void</code></td><td>none</td><td><strong>Accepted by the type but never called by the controller.</strong> Use the <code>activeTabChanged</code> event.</td></tr></tbody></table></div>\n<p><code>TabItem.enabled</code> / <code>visible</code> are data for the adapter; the controller does not check them.</p>\n","properties":"<h3 id=\"42-properties\">4.2 Properties<a class=\"anchor\" href=\"#42-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>activeTabIndex</code></td><td><code>number</code></td><td>r</td><td><code>0</code></td><td></td></tr><tr><td><code>tabs</code></td><td><code>readonly TabItem[]</code></td><td>r</td><td><code>[]</code></td><td></td></tr></tbody></table></div>\n","methods":"<h3 id=\"43-methods\">4.3 Methods<a class=\"anchor\" href=\"#43-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>setTabs(tabs: TabItem[])</code></td><td><code>void</code></td><td>no</td><td>Replaces the list with a copy. If <code>activeTabIndex &gt;= tabs.length</code>, it is clamped to <code>max(0, length - 1)</code> <strong>silently</strong> (no event).</td></tr><tr><td><code>setActiveTab(index: number)</code></td><td><code>Promise&lt;void&gt;</code></td><td>handler rejection</td><td>Ignored when <code>index</code> is out of range <code>[0, tabs.length)</code> or equals the current index. Otherwise sets it and raises <code>activeTabChanged</code>. Does <strong>not</strong> reject disabled (<code>enabled: false</code>) or hidden tabs.</td></tr></tbody></table></div>\n","events":"<h3 id=\"44-events\">4.4 Events<a class=\"anchor\" href=\"#44-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>activeTabChanged</code></td><td><code>{ activeIndex: number }</code></td><td>no</td><td>After the index changed via <code>setActiveTab</code>.</td><td>none</td></tr></tbody></table></div>\n","example":"<h3 id=\"45-example\">4.5 Example<a class=\"anchor\" href=\"#45-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> t = <span class=\"tok-k\">new</span> <span class=\"tok-t\">TabsController</span>({\n  tabs: [{ id: <span class=\"tok-s\">&quot;a&quot;</span>, headerText: <span class=\"tok-s\">&quot;A&quot;</span> }, { id: <span class=\"tok-s\">&quot;b&quot;</span>, headerText: <span class=\"tok-s\">&quot;B&quot;</span>, enabled: <span class=\"tok-k\">false</span> }, { id: <span class=\"tok-s\">&quot;c&quot;</span>, headerText: <span class=\"tok-s\">&quot;C&quot;</span> }],\n  onActiveTabChanged: (i) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;option callback&quot;</span>, i),    <span class=\"tok-c\">// never fires</span>\n});\nt.activeTabChanged.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;changed&quot;</span>, e.activeIndex));\n<span class=\"tok-k\">await</span> t.<span class=\"tok-f\">setActiveTab</span>(<span class=\"tok-n\">1</span>); <span class=\"tok-k\">await</span> t.<span class=\"tok-f\">setActiveTab</span>(<span class=\"tok-n\">1</span>); <span class=\"tok-k\">await</span> t.<span class=\"tok-f\">setActiveTab</span>(<span class=\"tok-n\">9</span>); <span class=\"tok-k\">await</span> t.<span class=\"tok-f\">setActiveTab</span>(-<span class=\"tok-n\">1</span>);\n<span class=\"tok-c\">// -&gt; changed 1          (disabled tab 1 was selected; duplicates/out-of-range ignored)</span>\nconsole.<span class=\"tok-f\">log</span>(t.activeTabIndex);   <span class=\"tok-c\">// -&gt; 1</span>\n<span class=\"tok-k\">await</span> t.<span class=\"tok-f\">setActiveTab</span>(<span class=\"tok-n\">2</span>);         <span class=\"tok-c\">// -&gt; changed 2</span>\nt.<span class=\"tok-f\">setTabs</span>([{ id: <span class=\"tok-s\">&quot;a&quot;</span>, headerText: <span class=\"tok-s\">&quot;A&quot;</span> }]);\nconsole.<span class=\"tok-f\">log</span>(t.activeTabIndex, t.tabs.length);   <span class=\"tok-c\">// -&gt; 0 1   (clamped silently)</span>\nt.<span class=\"tok-f\">setTabs</span>([]);\nconsole.<span class=\"tok-f\">log</span>(t.activeTabIndex);   <span class=\"tok-c\">// -&gt; 0</span>\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">new</span> <span class=\"tok-t\">TabsController</span>({ activeTabIndex: <span class=\"tok-n\">5</span>, tabs: [{ id: <span class=\"tok-s\">&quot;x&quot;</span>, headerText: <span class=\"tok-s\">&quot;X&quot;</span> }] }).activeTabIndex);   <span class=\"tok-c\">// -&gt; 5</span></code></pre></div>\n<p>To honour <code>enabled</code>, guard in your handler: <code>if (tabs.tabs[i]?.enabled === false) return; await tabs.setActiveTab(i);</code>.</p>\n<hr>\n"},"accordioncontroller":{"overview":"<p>Single-open-pane state. ASP.NET equivalent: <code>Accordion</code>.</p>\n","types-and-constructor-options":"<h3 id=\"51-types-and-constructor-options\">5.1 Types and constructor options<a class=\"anchor\" href=\"#51-types-and-constructor-options\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">interface</span> <span class=\"tok-t\">AccordionPaneItem</span> { id: string; headerText: string }\n<span class=\"tok-k\">interface</span> <span class=\"tok-t\">AccordionOptions</span> { selectedIndex?: number; panes?: <span class=\"tok-t\">AccordionPaneItem</span>[] }</code></pre></div>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>selectedIndex</code></td><td><code>number</code></td><td><code>0</code></td><td>Initially open pane. <code>-1</code> = none. Not validated.</td></tr><tr><td><code>panes</code></td><td><code>AccordionPaneItem[]</code></td><td><code>[]</code></td><td>Stored by reference.</td></tr></tbody></table></div>\n","properties":"<h3 id=\"52-properties\">5.2 Properties<a class=\"anchor\" href=\"#52-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>selectedIndex</code></td><td><code>number</code></td><td>r</td><td><code>0</code></td><td><code>-1</code> means all collapsed.</td></tr><tr><td><code>panes</code></td><td><code>readonly AccordionPaneItem[]</code></td><td>r</td><td><code>[]</code></td><td></td></tr></tbody></table></div>\n","methods":"<h3 id=\"53-methods\">5.3 Methods<a class=\"anchor\" href=\"#53-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>setPanes(panes: AccordionPaneItem[])</code></td><td><code>void</code></td><td>no</td><td>Replaces the list with a copy. Does <strong>not</strong> adjust <code>selectedIndex</code> and raises no event.</td></tr><tr><td><code>setSelectedIndex(index: number)</code></td><td><code>Promise&lt;void&gt;</code></td><td>handler rejection</td><td>If different from the current value: sets it (<strong>no bounds check</strong>; any number including <code>-1</code> or <code>42</code>) and raises <code>selectionChanged</code>.</td></tr><tr><td><code>togglePane(index: number)</code></td><td><code>Promise&lt;void&gt;</code></td><td>as above</td><td>If <code>index</code> is already selected, selects <code>-1</code> (collapse); otherwise selects <code>index</code>.</td></tr></tbody></table></div>\n","events":"<h3 id=\"54-events\">5.4 Events<a class=\"anchor\" href=\"#54-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>selectionChanged</code></td><td><code>{ selectedIndex: number }</code></td><td>no</td><td>After the value changed.</td><td>none</td></tr></tbody></table></div>\n","example":"<h3 id=\"55-example\">5.5 Example<a class=\"anchor\" href=\"#55-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> a = <span class=\"tok-k\">new</span> <span class=\"tok-t\">AccordionController</span>({ panes: [{ id: <span class=\"tok-s\">&quot;p1&quot;</span>, headerText: <span class=\"tok-s\">&quot;1&quot;</span> }, { id: <span class=\"tok-s\">&quot;p2&quot;</span>, headerText: <span class=\"tok-s\">&quot;2&quot;</span> }] });\na.selectionChanged.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;sel&quot;</span>, e.selectedIndex));\n<span class=\"tok-k\">await</span> a.<span class=\"tok-f\">togglePane</span>(<span class=\"tok-n\">0</span>);          <span class=\"tok-c\">// -&gt; sel -1  (pane 0 was open by default)</span>\n<span class=\"tok-k\">await</span> a.<span class=\"tok-f\">togglePane</span>(<span class=\"tok-n\">0</span>);          <span class=\"tok-c\">// -&gt; sel 0</span>\n<span class=\"tok-k\">await</span> a.<span class=\"tok-f\">togglePane</span>(<span class=\"tok-n\">1</span>);          <span class=\"tok-c\">// -&gt; sel 1</span>\n<span class=\"tok-k\">await</span> a.<span class=\"tok-f\">setSelectedIndex</span>(<span class=\"tok-n\">1</span>);    <span class=\"tok-c\">// no event (unchanged)</span>\n<span class=\"tok-k\">await</span> a.<span class=\"tok-f\">setSelectedIndex</span>(<span class=\"tok-n\">42</span>);   <span class=\"tok-c\">// -&gt; sel 42  (not validated)</span>\nconsole.<span class=\"tok-f\">log</span>(a.selectedIndex, a.panes.length);   <span class=\"tok-c\">// -&gt; 42 2</span></code></pre></div>\n<hr>\n"},"autocompletebehavior":{"overview":"<p>Search orchestration with minimum prefix and optional result cache. ASP.NET equivalent: <code>AutoCompleteExtender</code>.</p>\n","constructor-options-autocompleteoptions":"<h3 id=\"61-constructor-options-autocompleteoptions\">6.1 Constructor options (<code>AutoCompleteOptions</code>)<a class=\"anchor\" href=\"#61-constructor-options-autocompleteoptions\" aria-label=\"Link to this section\">#</a></h3>\n<p>Constructor: <code>new AutoCompleteBehavior(options: AutoCompleteOptions = {})</code>; <code>options</code> is a public mutable field.</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>serviceMethod</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint; unused by core.</td></tr><tr><td><code>minimumPrefixLength</code></td><td><code>number</code></td><td><code>1</code> (when undefined)</td><td>Terms shorter than this return <code>[]</code> immediately (a <code>null</code>/<code>undefined</code> term counts as length 0). <code>0</code> allows the empty term.</td></tr><tr><td><code>completionInterval</code></td><td><code>number</code></td><td><code>undefined</code></td><td>Adapter hint (debounce); <strong>unused by core</strong>.</td></tr><tr><td><code>enableCaching</code></td><td><code>boolean</code></td><td><code>undefined</code> (off)</td><td>Cache results per exact term (case-sensitive).</td></tr><tr><td><code>completionSetCount</code></td><td><code>number</code></td><td><code>undefined</code></td><td>Adapter hint; <strong>unused</strong> (results are not truncated).</td></tr><tr><td><code>onSearch</code></td><td><code>(term: string) =&gt; Promise&lt;string[]&gt;</code></td><td><code>undefined</code></td><td>Data provider. Without it, <code>search</code> returns <code>[]</code> (events still fire).</td></tr></tbody></table></div>\n","properties":"<h3 id=\"62-properties\">6.2 Properties<a class=\"anchor\" href=\"#62-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>AutoCompleteOptions</code></td><td>rw</td><td><code>{}</code></td><td></td></tr></tbody></table></div>\n","methods":"<h3 id=\"63-methods\">6.3 Methods<a class=\"anchor\" href=\"#63-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>search(term: string)</code></td><td><code>Promise&lt;string[]&gt;</code></td><td><code>onSearch</code> / handler rejection</td><td>1) term shorter than <code>minimumPrefixLength</code> -&gt; <code>[]</code> (no events). 2) caching on and term cached -&gt; cached array (no events, no <code>onSearch</code>). 3) raise <code>searchTriggered</code>. 4) <code>onSearch(term)</code> if provided. 5) cache result if caching on. 6) raise <code>resultsLoaded</code>. Returns the results.</td></tr></tbody></table></div>\n","events":"<h3 id=\"64-events\">6.4 Events<a class=\"anchor\" href=\"#64-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>searchTriggered</code></td><td><code>{ term: string }</code></td><td>no</td><td>Before calling <code>onSearch</code> (not on cache hit or too-short term).</td><td>none</td></tr><tr><td><code>resultsLoaded</code></td><td><code>{ results: string[] }</code></td><td>no</td><td>After <code>onSearch</code> (and cache write).</td><td>none (it is the same array that is returned and cached; mutating it affects the cache)</td></tr></tbody></table></div>\n","example":"<h3 id=\"65-example\">6.5 Example<a class=\"anchor\" href=\"#65-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">let</span> calls = <span class=\"tok-n\">0</span>;\n<span class=\"tok-k\">const</span> ac = <span class=\"tok-k\">new</span> <span class=\"tok-t\">AutoCompleteBehavior</span>({\n  minimumPrefixLength: <span class=\"tok-n\">2</span>, enableCaching: <span class=\"tok-k\">true</span>,\n  onSearch: <span class=\"tok-k\">async</span> (t) =&gt; { calls++; <span class=\"tok-k\">return</span> [<span class=\"tok-s\">&quot;alpha&quot;</span>, <span class=\"tok-s\">&quot;alps&quot;</span>, <span class=\"tok-s\">&quot;beta&quot;</span>].<span class=\"tok-f\">filter</span>((x) =&gt; x.<span class=\"tok-f\">startsWith</span>(t)); },\n});\nac.searchTriggered.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;searchTriggered&quot;</span>, e.term));\nac.resultsLoaded.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;resultsLoaded&quot;</span>, e.results));\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> ac.<span class=\"tok-f\">search</span>(<span class=\"tok-s\">&quot;a&quot;</span>), <span class=\"tok-k\">await</span> ac.<span class=\"tok-f\">search</span>(<span class=\"tok-s\">&quot;al&quot;</span>), <span class=\"tok-k\">await</span> ac.<span class=\"tok-f\">search</span>(<span class=\"tok-s\">&quot;al&quot;</span>), <span class=\"tok-k\">await</span> ac.<span class=\"tok-f\">search</span>(<span class=\"tok-s\">&quot;AL&quot;</span>), calls);\n<span class=\"tok-c\">// -&gt; searchTriggered al / resultsLoaded [ 'alpha', 'alps' ]</span>\n<span class=\"tok-c\">// -&gt; searchTriggered AL / resultsLoaded []</span>\n<span class=\"tok-c\">// -&gt; [] [ 'alpha', 'alps' ] [ 'alpha', 'alps' ] [] 2</span>\n<span class=\"tok-k\">const</span> none = <span class=\"tok-k\">new</span> <span class=\"tok-t\">AutoCompleteBehavior</span>();\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> none.<span class=\"tok-f\">search</span>(<span class=\"tok-s\">&quot;x&quot;</span>), <span class=\"tok-k\">await</span> none.<span class=\"tok-f\">search</span>(<span class=\"tok-s\">&quot;&quot;</span>), <span class=\"tok-k\">await</span> none.<span class=\"tok-f\">search</span>(<span class=\"tok-k\">undefined</span>));   <span class=\"tok-c\">// -&gt; [] [] []</span></code></pre></div>\n<p>Gotchas: the cache never expires and is not cleared by any method; there is no debounce and no out-of-order-response protection (a slow earlier request can still emit <code>resultsLoaded</code> after a newer one); <code>search</code> of a rejected <code>onSearch</code> is not cached.</p>\n<hr>\n"},"confirmbuttonbehavior":{"overview":"<p>Confirmation prompt before an action. ASP.NET equivalent: <code>ConfirmButtonExtender</code>.</p>\n","constructor-options-confirmbuttonoptions":"<h3 id=\"71-constructor-options-confirmbuttonoptions\">7.1 Constructor options (<code>ConfirmButtonOptions</code>)<a class=\"anchor\" href=\"#71-constructor-options-confirmbuttonoptions\" aria-label=\"Link to this section\">#</a></h3>\n<p>Constructor: <code>new ConfirmButtonBehavior(options: ConfirmButtonOptions)</code> (required).</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>confirmText</code></td><td><code>string</code></td><td><strong>required</strong></td><td>Text passed to <code>window.confirm</code>.</td></tr><tr><td><code>confirmTitle</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint; <code>window.confirm</code> has no title, so unused by core.</td></tr><tr><td><code>onConfirm</code></td><td><code>() =&gt; Promise&lt;void&gt; | void</code></td><td><code>undefined</code></td><td>Awaited when the user confirms.</td></tr><tr><td><code>onCancel</code></td><td><code>() =&gt; void</code></td><td><code>undefined</code></td><td>Called when the user declines.</td></tr></tbody></table></div>\n","properties":"<h3 id=\"72-properties\">7.2 Properties<a class=\"anchor\" href=\"#72-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>ConfirmButtonOptions</code></td><td>rw</td><td>required</td><td></td></tr></tbody></table></div>\n","methods":"<h3 id=\"73-methods\">7.3 Methods<a class=\"anchor\" href=\"#73-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>execute()</code></td><td><code>Promise&lt;boolean&gt;</code></td><td><code>onConfirm</code> rejection</td><td>If a global <code>window.confirm</code> function exists: calls it with <code>confirmText</code>. Confirmed -&gt; awaits <code>onConfirm</code>, returns <code>true</code>. Declined -&gt; calls <code>onCancel</code>, returns <code>false</code>. <strong>If there is no <code>window.confirm</code> (Node, SSR, workers) returns <code>true</code> without calling <code>onConfirm</code> or <code>onCancel</code>.</strong></td></tr></tbody></table></div>\n","events":"<h3 id=\"74-events\">7.4 Events<a class=\"anchor\" href=\"#74-events\" aria-label=\"Link to this section\">#</a></h3>\n<p>None.</p>\n","example":"<h3 id=\"75-example\">7.5 Example<a class=\"anchor\" href=\"#75-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> cb = <span class=\"tok-k\">new</span> <span class=\"tok-t\">ConfirmButtonBehavior</span>({ confirmText: <span class=\"tok-s\">&quot;Delete?&quot;</span>, onConfirm: () =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;deleted&quot;</span>), onCancel: () =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;cancelled&quot;</span>) });\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;no window:&quot;</span>, <span class=\"tok-k\">await</span> cb.<span class=\"tok-f\">execute</span>());          <span class=\"tok-c\">// -&gt; no window: true   (callbacks NOT called)</span>\nglobalThis.window = { confirm: (t) =&gt; { console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;confirm:&quot;</span>, t); <span class=\"tok-k\">return</span> <span class=\"tok-k\">false</span>; } };\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cb.<span class=\"tok-f\">execute</span>());                        <span class=\"tok-c\">// -&gt; confirm: Delete? / cancelled / false</span>\nglobalThis.window = { confirm: () =&gt; <span class=\"tok-k\">true</span> };\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cb.<span class=\"tok-f\">execute</span>());                        <span class=\"tok-c\">// -&gt; deleted / true</span></code></pre></div>\n<p>Gotcha: because <code>execute()</code> returns <code>true</code> without running <code>onConfirm</code> when no <code>window.confirm</code> exists, do not rely on <code>onConfirm</code> for the destructive action in non-browser environments; use the boolean result: <code>if (await cb.execute()) doDelete();</code> works in both cases.</p>\n<hr>\n"},"collapsiblepanelbehavior":{"overview":"<p>Collapsed/expanded state. ASP.NET equivalent: <code>CollapsiblePanelExtender</code>.</p>\n","constructor-options-collapsiblepaneloptions":"<h3 id=\"81-constructor-options-collapsiblepaneloptions\">8.1 Constructor options (<code>CollapsiblePanelOptions</code>)<a class=\"anchor\" href=\"#81-constructor-options-collapsiblepaneloptions\" aria-label=\"Link to this section\">#</a></h3>\n<p>Constructor: <code>new CollapsiblePanelBehavior(options: CollapsiblePanelOptions = {})</code>.</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>collapsed</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Initial state.</td></tr><tr><td><code>collapseControlId</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>expandControlId</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>textLabelId</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>collapsedText</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint (label while collapsed).</td></tr><tr><td><code>expandedText</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint (label while expanded).</td></tr></tbody></table></div>\n","properties":"<h3 id=\"82-properties\">8.2 Properties<a class=\"anchor\" href=\"#82-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>CollapsiblePanelOptions</code></td><td>rw</td><td><code>{}</code></td><td></td></tr><tr><td><code>isCollapsed</code></td><td><code>boolean</code></td><td>r</td><td><code>options.collapsed ?? false</code></td><td></td></tr></tbody></table></div>\n","methods":"<h3 id=\"83-methods\">8.3 Methods<a class=\"anchor\" href=\"#83-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>setCollapsed(collapsed: boolean)</code></td><td><code>void</code></td><td>no</td><td>If different from the current state: updates it and raises <code>stateChanged</code> <strong>without awaiting</strong> (<code>void</code>). No-op otherwise.</td></tr><tr><td><code>toggle()</code></td><td><code>void</code></td><td>no</td><td><code>setCollapsed(!isCollapsed)</code>.</td></tr></tbody></table></div>\n","events":"<h3 id=\"84-events\">8.4 Events<a class=\"anchor\" href=\"#84-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>stateChanged</code></td><td><code>{ collapsed: boolean }</code></td><td>no</td><td>After a real change. Fire-and-forget: sync handlers run immediately; async handlers' rejections are unhandled.</td><td>none</td></tr></tbody></table></div>\n","example":"<h3 id=\"85-example\">8.5 Example<a class=\"anchor\" href=\"#85-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> c = <span class=\"tok-k\">new</span> <span class=\"tok-t\">CollapsiblePanelBehavior</span>({ collapsed: <span class=\"tok-k\">true</span> });\nc.stateChanged.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;state&quot;</span>, e.collapsed));\nconsole.<span class=\"tok-f\">log</span>(c.isCollapsed);   <span class=\"tok-c\">// -&gt; true</span>\nc.<span class=\"tok-f\">toggle</span>();                   <span class=\"tok-c\">// -&gt; state false</span>\nc.<span class=\"tok-f\">setCollapsed</span>(<span class=\"tok-k\">false</span>);        <span class=\"tok-c\">// (no change, no event)</span>\nc.<span class=\"tok-f\">setCollapsed</span>(<span class=\"tok-k\">true</span>);         <span class=\"tok-c\">// -&gt; state true</span>\nconsole.<span class=\"tok-f\">log</span>(c.isCollapsed);   <span class=\"tok-c\">// -&gt; true</span></code></pre></div>\n<hr>\n"},"cascadingdropdownbehavior":{"overview":"<p>Loads child list items when a parent selection changes. ASP.NET equivalent: <code>CascadingDropDown</code>.</p>\n","constructor-options-cascadingdropdownoptions":"<h3 id=\"91-constructor-options-cascadingdropdownoptions\">9.1 Constructor options (<code>CascadingDropDownOptions</code>)<a class=\"anchor\" href=\"#91-constructor-options-cascadingdropdownoptions\" aria-label=\"Link to this section\">#</a></h3>\n<p>Constructor: <code>new CascadingDropDownBehavior(options: CascadingDropDownOptions)</code> (required).</p>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>category</code></td><td><code>string</code></td><td><strong>required</strong></td><td>Category name (adapter hint).</td></tr><tr><td><code>parentControlId</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>promptText</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint (e.g. &quot;-- pick --&quot;); core does not insert it into results.</td></tr><tr><td><code>loadingText</code></td><td><code>string</code></td><td><code>undefined</code></td><td>Adapter hint.</td></tr><tr><td><code>loadItems</code></td><td><code>(parentValue: string) =&gt; Promise&lt;Array&lt;{ text: string; value: string }&gt;&gt;</code></td><td><code>undefined</code></td><td>Data provider.</td></tr></tbody></table></div>\n","properties":"<h3 id=\"92-properties\">9.2 Properties<a class=\"anchor\" href=\"#92-properties\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Type</th><th>R/W</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td><code>CascadingDropDownOptions</code></td><td>rw</td><td>required</td><td></td></tr></tbody></table></div>\n","methods":"<h3 id=\"93-methods\">9.3 Methods<a class=\"anchor\" href=\"#93-methods\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Signature</th><th>Returns</th><th>Throws</th><th>Description</th></tr></thead><tbody><tr><td><code>onParentChange(parentValue: string)</code></td><td><code>Promise&lt;Array&lt;{ text: string; value: string }&gt;&gt;</code></td><td><code>loadItems</code> / handler rejection (not caught)</td><td>No <code>loadItems</code> -&gt; <code>[]</code> (no event). Else awaits <code>loadItems(parentValue)</code>, raises <code>itemsLoaded</code>, returns the items.</td></tr></tbody></table></div>\n","events":"<h3 id=\"94-events\">9.4 Events<a class=\"anchor\" href=\"#94-events\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-scroll\"><table><thead><tr><th>Name</th><th>Args type</th><th>Cancellable</th><th>Raised when</th><th>Mutable fields</th></tr></thead><tbody><tr><td><code>itemsLoaded</code></td><td><code>{ items: Array&lt;{ text: string; value: string }&gt; }</code></td><td>no</td><td>After <code>loadItems</code> resolved (also for an empty list).</td><td>none</td></tr></tbody></table></div>\n","example":"<h3 id=\"95-example\">9.5 Example<a class=\"anchor\" href=\"#95-example\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> states = { <span class=\"tok-t\">US</span>: [<span class=\"tok-s\">&quot;NY&quot;</span>, <span class=\"tok-s\">&quot;CA&quot;</span>], <span class=\"tok-t\">CA</span>: [<span class=\"tok-s\">&quot;ON&quot;</span>] };\n<span class=\"tok-k\">const</span> cd = <span class=\"tok-k\">new</span> <span class=\"tok-t\">CascadingDropDownBehavior</span>({\n  category: <span class=\"tok-s\">&quot;state&quot;</span>, parentControlId: <span class=\"tok-s\">&quot;country&quot;</span>, promptText: <span class=\"tok-s\">&quot;-- pick --&quot;</span>,\n  loadItems: <span class=\"tok-k\">async</span> (p) =&gt; (states[p] ?? []).<span class=\"tok-f\">map</span>((s) =&gt; ({ text: s, value: s.<span class=\"tok-f\">toLowerCase</span>() })),\n});\ncd.itemsLoaded.<span class=\"tok-f\">subscribe</span>((s, e) =&gt; console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;itemsLoaded&quot;</span>, e.items.length));\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> cd.<span class=\"tok-f\">onParentChange</span>(<span class=\"tok-s\">&quot;US&quot;</span>), <span class=\"tok-k\">await</span> cd.<span class=\"tok-f\">onParentChange</span>(<span class=\"tok-s\">&quot;ZZ&quot;</span>));\n<span class=\"tok-c\">// -&gt; itemsLoaded 2 / itemsLoaded 0</span>\n<span class=\"tok-c\">// -&gt; [ { text: 'NY', value: 'ny' }, { text: 'CA', value: 'ca' } ] []</span>\nconsole.<span class=\"tok-f\">log</span>(<span class=\"tok-k\">await</span> <span class=\"tok-k\">new</span> <span class=\"tok-t\">CascadingDropDownBehavior</span>({ category: <span class=\"tok-s\">&quot;x&quot;</span> }).<span class=\"tok-f\">onParentChange</span>(<span class=\"tok-s\">&quot;US&quot;</span>));   <span class=\"tok-c\">// -&gt; []</span>\n<span class=\"tok-k\">const</span> bad = <span class=\"tok-k\">new</span> <span class=\"tok-t\">CascadingDropDownBehavior</span>({ category: <span class=\"tok-s\">&quot;x&quot;</span>, loadItems: <span class=\"tok-k\">async</span> () =&gt; { <span class=\"tok-k\">throw</span> <span class=\"tok-k\">new</span> <span class=\"tok-t\">Error</span>(<span class=\"tok-s\">&quot;net&quot;</span>); } });\n<span class=\"tok-k\">try</span> { <span class=\"tok-k\">await</span> bad.<span class=\"tok-f\">onParentChange</span>(<span class=\"tok-s\">&quot;US&quot;</span>); } <span class=\"tok-k\">catch</span> (e) { console.<span class=\"tok-f\">log</span>(<span class=\"tok-s\">&quot;throws&quot;</span>, e.message); }      <span class=\"tok-c\">// -&gt; throws net</span></code></pre></div>\n<p>Gotchas: no stale-response protection (if the user changes the parent twice quickly, whichever promise resolves last wins in your handler); a <code>loadItems</code> rejection is propagated, so wrap the call in <code>try/catch</code>.</p>\n<hr>\n"},"more-examples":{"examples":"<ul class=\"aa-doc-index\"><li><a href=\"#/api/behaviors/more-examples/examples/101-confirm-then-delete-with-a-modal\">Confirm-then-delete with a modal</a></li><li><a href=\"#/api/behaviors/more-examples/examples/102-wizard-style-tabs-that-skip-disabled-tabs\">Wizard-style tabs that skip disabled tabs</a></li><li><a href=\"#/api/behaviors/more-examples/examples/103-multi-open-accordion-from-several-controllers\">Multi-open accordion from several controllers</a></li><li><a href=\"#/api/behaviors/more-examples/examples/104-debounced-autocomplete-the-behavior-has-no-debounce\">Debounced autocomplete (the behavior has no debounce)</a></li></ul><h3 id=\"101-confirm-then-delete-with-a-modal\">10.1 Confirm-then-delete with a modal<a class=\"anchor\" href=\"#101-confirm-then-delete-with-a-modal\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">const</span> modal = <span class=\"tok-k\">new</span> <span class=\"tok-t\">ModalBehavior</span>({ onOk: <span class=\"tok-k\">async</span> () =&gt; <span class=\"tok-k\">await</span> <span class=\"tok-f\">deleteRow</span>(<span class=\"tok-n\">42</span>) });\ndocument.<span class=\"tok-f\">querySelector</span>(<span class=\"tok-s\">&quot;#delete&quot;</span>).<span class=\"tok-f\">addEventListener</span>(<span class=\"tok-s\">&quot;click&quot;</span>, () =&gt; modal.<span class=\"tok-f\">show</span>());\n<span class=\"tok-c\">// adapter buttons: OK -&gt; modal.handleOk(), Cancel -&gt; modal.handleCancel()</span></code></pre></div>\n<h3 id=\"102-wizard-style-tabs-that-skip-disabled-tabs\">10.2 Wizard-style tabs that skip disabled tabs<a class=\"anchor\" href=\"#102-wizard-style-tabs-that-skip-disabled-tabs\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">async</span> <span class=\"tok-k\">function</span> <span class=\"tok-f\">goNext</span>(t: <span class=\"tok-t\">TabsController</span>) {\n  <span class=\"tok-k\">for</span> (<span class=\"tok-k\">let</span> i = t.activeTabIndex + <span class=\"tok-n\">1</span>; i &lt; t.tabs.length; i++) {\n    <span class=\"tok-k\">if</span> (t.tabs[i]?.enabled !== <span class=\"tok-k\">false</span>) { <span class=\"tok-k\">await</span> t.<span class=\"tok-f\">setActiveTab</span>(i); <span class=\"tok-k\">return</span>; }\n  }\n}</code></pre></div>\n<h3 id=\"103-multi-open-accordion-from-several-controllers\">10.3 Multi-open accordion from several controllers<a class=\"anchor\" href=\"#103-multi-open-accordion-from-several-controllers\" aria-label=\"Link to this section\">#</a></h3>\n<p>Use one <code>CollapsiblePanelBehavior</code> per section if you need independent expand/collapse; <code>AccordionController</code> always keeps at most one pane open.</p>\n<h3 id=\"104-debounced-autocomplete-the-behavior-has-no-debounce\">10.4 Debounced autocomplete (the behavior has no debounce)<a class=\"anchor\" href=\"#104-debounced-autocomplete-the-behavior-has-no-debounce\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"code-block\"><div class=\"code-head\"><span class=\"code-lang\">ts</span><button class=\"copy-btn\" type=\"button\" aria-label=\"Copy code\">Copy</button></div><pre><code class=\"lang-ts\"><span class=\"tok-k\">let</span> timer: <span class=\"tok-t\">ReturnType</span>&lt;<span class=\"tok-k\">typeof</span> setTimeout&gt;;\n<span class=\"tok-k\">const</span> onInput = (value: string) =&gt; { <span class=\"tok-f\">clearTimeout</span>(timer); timer = <span class=\"tok-f\">setTimeout</span>(() =&gt; ac.<span class=\"tok-f\">search</span>(value).<span class=\"tok-f\">then</span>(render), ac.options.completionInterval ?? <span class=\"tok-n\">300</span>); };</code></pre></div>\n<hr>\n"},"gotchas-and-known-inconsistencies":{"overview":"<ul><li><code>TabsController</code> option <code>onActiveTabChanged</code> is never invoked.</li><li><code>TabsController.setActiveTab</code> ignores <code>enabled</code>/<code>visible</code>; <code>AccordionController.setSelectedIndex</code> has no bounds check; <code>setTabs</code>/<code>setPanes</code> do not emit when the index changes or stays out of range (accordion: no clamping at all).</li><li><code>ModalBehavior</code> / <code>CollapsiblePanelBehavior</code> / <code>CascadingDropDownBehavior</code> id options are inert hints; <code>AutoCompleteOptions.completionInterval</code>, <code>completionSetCount</code>, <code>serviceMethod</code> and <code>ConfirmButtonOptions.confirmTitle</code> are also inert in core.</li><li><code>ConfirmButtonBehavior.execute()</code> returns <code>true</code> without calling <code>onConfirm</code> when <code>window.confirm</code> is unavailable.</li><li><code>CollapsiblePanelBehavior.stateChanged</code> is fire-and-forget while every other behavior event is awaited.</li><li>No behavior event is cancellable (<code>CancelEventArgs</code> is not used), unlike the rest of the library.</li><li><code>TabsController</code>/<code>AccordionController</code> store the arrays passed to the constructor by reference (setters copy).</li></ul>"}};
export default area;
